INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48211, 'Isaiah 37:20', 'Isaiah', 37, 20, 'نو زمونږ څښتن خدایه، مونږ د اشوریانو څخه وژغوره، ترڅو د نړۍ ټولې پاچاهۍ په دې پوه شي چې یوازې ته څښتن یې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_20.mp3', '', 1761754199, 1761754199),
(48212, 'Isaiah 37:21', 'Isaiah', 37, 21, 'نو د آموص زوی اشعیا حزقیا پاچا ته دا پیغام ورولېږه: «د اسراییلو څښتن خدای داسې وایي: ‹په دې خاطر چې تا د اشور د پاچا سنخاریب په هکله دعا وکړه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_21.mp3', '', 1761754199, 1761754199),
(48213, 'Isaiah 37:22', 'Isaiah', 37, 22, 'نو زه د هغه په ځواب کې داسې وایم: اورشلیم د یوې پېغلې انجلۍ په شان دی چې ستا څخه کرکه کوي او په تا باندې ملنډې وهي. کله چې ته تښتې، نو هغوی په تا پورې خندا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_22.mp3', '', 1761754199, 1761754199),
(48214, 'Isaiah 37:23', 'Isaiah', 37, 23, 'ای سنخاریبه! تا ماته، یعنې د اسراییلو سپېڅلي خدای ته سپکاوی کړی او کفر دې ویلی دی، خپل اواز دې اوچت کړی او چاته دې د غرور په سترګه کتلي دي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_23.mp3', '', 1761754199, 1761754199),
(48215, 'Isaiah 37:24', 'Isaiah', 37, 24, 'تا په خپلو نوکرانو زه څښتن سپک کړم او د خپل ځان په اړه دې داسې لاپې وهلې دي: ما خپلې جنګي ګاډۍ د لبنان ډېرو لوړو ځایونو ته خېژولې دي، د هغه ځنګل تر ټولو لوړ ځای ته ختلی یم او د سبر او سروې ډېرې ښې ونې مې پرې کړې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_24.mp3', '', 1761754199, 1761754199),
(48216, 'Isaiah 37:25', 'Isaiah', 37, 25, 'تا لافې ووهلې چې ما په پردیو هېوادونو کې د هغو څاه ګانو اوبه وڅښلې چې ما کیندلې وې او په خپلو پښو باندې مې د مصر ټول سیندونه وچ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_25.mp3', '', 1761754199, 1761754199),
(48217, 'Isaiah 37:26', 'Isaiah', 37, 26, 'ایا تا دا نه دي اورېدلي چې دا هرڅه مې پخوا پلان کړي وو او حتی په دې نه پوهېږې چې دا یوازې زه وم چې دا پرېکړه مې وکړه چې ته به دا کار کوې؟ ته مې پرېښودلې چې هغه قوي ښارونه وران کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_26.mp3', '', 1761754199, 1761754199),
(48218, 'Isaiah 37:27', 'Isaiah', 37, 27, 'د هغو ځایونو خلک کمزوري او ډېر سخت وارخطا شول. هغوی د پټیو د بوټو یا د هغو تنکیو واښو په شان وو چې د کوټو په سر باندې شنه کیږي او کله چې هوا توده شي، نو هغه مړاوي کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_27.mp3', '', 1761754199, 1761754199),
(48219, 'Isaiah 37:28', 'Isaiah', 37, 28, 'خو ای سنخاریبه، زه خبر یم چې ته چېرته اوسېږې او څه وخت ځې او راځې. همدارنګه زه پوهېږم چې څومره ماته په قهر یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_28.mp3', '', 1761754199, 1761754199),
(48220, 'Isaiah 37:29', 'Isaiah', 37, 29, 'ما ستا قهر چې زما په وړاندې یې لرې لیدلی او ستا د غرور نه خبر یم. نو زه به ستا په پوزه کې چنګک او ستا په خوله کې قیضه واچوم او په کومه لاره چې راغلی یې، په هماغې لارې به دې بېرته ولېږم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_29.mp3', '', 1761754199, 1761754199),
(48221, 'Isaiah 37:30', 'Isaiah', 37, 30, 'بیا اشعیا حزقیا پاچا ته وویل: «دا به د هغه څه نښه وي چې پېښ به شي. سږکال او راتلونکی کال به ته هغه غلې دانې وخورې چې په خپله شنې کیږي، خو په درېم کال به ته وکولای شې چې خپلې غلې دانې وکرې او حاصل به یې واخلې او د انګورو تاکونه به وکرې او انګور به یې وخورې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_30.mp3', '', 1761754199, 1761754199),
(48222, 'Isaiah 37:31', 'Isaiah', 37, 31, 'هغوی چې په یهودا کې ژوندي پاتې دي د نباتاتو په شان به په ځمکه کې ژورې ریښې وکړي او مېوه به ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_31.mp3', '', 1761754199, 1761754199),
(48223, 'Isaiah 37:32', 'Isaiah', 37, 32, 'په اورشلیم او د صهیون په غره کې به یو شمېر خلک ژوندي پاتې شي، ځکه چې مطلق قادر څښتن به په خپل غیرت باندې دا کار وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_32.mp3', '', 1761754199, 1761754199),
(48224, 'Isaiah 37:33', 'Isaiah', 37, 33, 'څښتن د اشور د پاچا په هکله داسې وایي: ‹هغه به د اورشلیم ښار ته داخل نه شي او یو غشی به هم په هغه باندې ګوزار نه کړي. هېڅ عسکر به د خپلو سپرونو سره دې ښار ته ورنژدې نه شي او د هغه شاوخوا به د خاورو ډېرۍ جوړې نه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_33.mp3', '', 1761754199, 1761754199),
(48225, 'Isaiah 37:34', 'Isaiah', 37, 34, 'څښتن داسې وایي: په هغې لارې چې هغه راغلی دی بېرته به په هماغې لارې لاړ شي او ښار ته به داخل نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_34.mp3', '', 1761754199, 1761754199),
(48226, 'Isaiah 37:35', 'Isaiah', 37, 35, 'زه به د دې ښار څخه د خپل ځان په اړه او د خپلې هغې وعدې په اړه چې د خپل خدمتګار داود سره مې کړې وه، دفاع وکړم او هغه به وساتم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_35.mp3', '', 1761754199, 1761754199),
(48227, 'Isaiah 37:36', 'Isaiah', 37, 36, 'د څښتن فرښته د اشوریانو کمپ ته ورغله او ۱۸۵۰۰۰ عسکر یې ووژل. کله چې سهار وختي خلک راپاڅېدل، نو ویې لیدل چې په هغه ځای کې مړي پراته دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_36.mp3', '', 1761754199, 1761754199),
(48228, 'Isaiah 37:37', 'Isaiah', 37, 37, 'نو سنخاریب پاچا بېرته اشور ته ستون شو او د نینوا په ښار کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_37.mp3', '', 1761754199, 1761754199),
(48229, 'Isaiah 37:38', 'Isaiah', 37, 38, 'یوه ورځ چې هغه د خپل خدای نسروک د عبادت په ځای کې عبادت کاوه، د هغه دوو زامنو ادرملک او شرازر په خپلو تورو باندې هغه وواژه او بیا هغوی د ارارات خاورې ته وتښتېدل. د هغه بل زوی چې اسرحدون نومېده د هغه په ځای پاچا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_38.mp3', '', 1761754199, 1761754199),
(48230, 'Isaiah 7:1', 'Isaiah', 7, 1, 'کله چې احاز د یوتام زوی او د عزیا لمسی د یهودا پاچا ؤ، د سوریې پاچا رزین او د اسراییلو پاچا د رملیا زوی فقح په اورشلیم باندې حمله وکړه، خو ویې نه شو کولای چې هغه فتح کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_1.mp3', '', 1761754199, 1761754199),
(48231, 'Isaiah 7:2', 'Isaiah', 7, 2, 'کله چې دا خبر د داود اولادې یعنې د یهودا پاچا، احاز ته ورسېده چې د سوریې لښکرې د اسراییلو سره یوځای شوې، د پاچا او د هغه د خلکو زړونه داسې رپېدل لکه ونې چې په باد کې رپیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_2.mp3', '', 1761754199, 1761754199),
(48232, 'Isaiah 7:3', 'Isaiah', 7, 3, 'څښتن اشعیا ته وویل: «د خپل زوی شاریاشوب سره لاړ شه او له آحاز پاچا سره وګوره. تاسو به هغه د پاسني ډنډ د لښتي په سر چې د کالیو وینځونکو د پټي په لاره کې پرته ده، پیدا کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_3.mp3', '', 1761754199, 1761754199),
(48233, 'Isaiah 7:4', 'Isaiah', 7, 4, 'احاز ته ووایه چې پام وکړي، ارام اوسي او د هغو دواړو پاچاهانو یعنې د رزین او د هغه د سوریایي لښکرو او د رملیا د زوی له نقشو څخه ونه وېریږي او زړونه ونه بایلي. د هغوی قهر یوازې د هغو دوو ټوټو لرګیو د لوګي په شان دی چې د هغه څخه راپورته کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_4.mp3', '', 1761754199, 1761754199),
(48234, 'Isaiah 7:5', 'Isaiah', 7, 5, 'سوریې د اسراییلو او د رملیا د زوی سره یوځای ستا په وړاندې دسیسه جوړه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_5.mp3', '', 1761754199, 1761754199),
(48235, 'Isaiah 7:6', 'Isaiah', 7, 6, 'هغوی نیت لري چې په یهودا باندې حمله وکړي، خلک ووېروي، هغه فتح کړي او بیا د تبییل زوی په تخت باندې کښېنوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_6.mp3', '', 1761754199, 1761754199),
(48236, 'Isaiah 7:7', 'Isaiah', 7, 7, 'خو زه څښتن تعالی دا وایم چې داسې به هېڅکله ونه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_7.mp3', '', 1761754199, 1761754199),
(48237, 'Isaiah 7:8', 'Isaiah', 7, 8, 'ولې؟ ځکه چې رزین پاچا کمزوری دی، دمشق چې د سوریې پایتخت دی قوي نه دی، نو ښکاره ده چې سوریه کمزورې ده. خو د اسراییل په اړه باید وویل شي چې هغه به په پنځه شپېتو کالو کې ټوټې ټوټې شي او هغه به د یو قوم په شان پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_8.mp3', '', 1761754199, 1761754199),
(48238, 'Isaiah 7:9', 'Isaiah', 7, 9, 'همدارنګه د رملیا زوی کمزوری دی، سامره چې د اسراییلو پایتخت دی، قوي نه دی او ښکاره ده چې اسراییل کمزوری دی. که چېرې ستاسو ایمان ټینګ نه وي، نو په رښتیا به تاسو هم ټینګ پاتې نه شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_9.mp3', '', 1761754199, 1761754199),
(48239, 'Isaiah 7:10', 'Isaiah', 7, 10, 'څښتن احاز ته یو بل پیغام ورولېږه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_10.mp3', '', 1761754199, 1761754199),
(48240, 'Isaiah 7:11', 'Isaiah', 7, 11, '«د خپل څښتن خدای څخه وغواړه چې یوه نښه د ثبوت په توګه درکړي. داسې شیان وغواړه چې هغه د مړو د دنیا په ژور ځای کې یا پورته په اسمان کې وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_11.mp3', '', 1761754199, 1761754199),
(48241, 'Isaiah 7:12', 'Isaiah', 7, 12, 'احاز په ځواب کې وویل: «زه نښې ته اړتیا نه لرم او زه نه غواړم چې څښتن وازمایم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_12.mp3', '', 1761754199, 1761754199),
(48242, 'Isaiah 7:13', 'Isaiah', 7, 13, 'اشعیا وویل: «ای د داود د پاچا اولادې، اوس غوږ ونیسئ. ایا دا ستاسو دپاره کافي نه وه چې خلک مو بې حوصلې کړل؟ او اوس غواړئ چې زما خدای هم بې حوصلې کړئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_13.mp3', '', 1761754199, 1761754199),
(48243, 'Isaiah 7:14', 'Isaiah', 7, 14, 'نو ښه ده، څښتن به خپله تاسو ته یوه نښه دروښایي او هغه دا ده: پېغله به امیدواره شي، هغه به یو زوی وزېږوي او په هغه باندې به عمانوییل نوم کېږدي، چې معنی یې ده: ‹خدای زمونږ سره مل دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_14.mp3', '', 1761754199, 1761754199),
(48244, 'Isaiah 7:17', 'Isaiah', 7, 17, 'خو څښتن به په تا، ستا په خلکو او په ټوله شاهي کورنۍ باندې سختې ورځې راولي. له هغه وخت راهیسې چې د اسراییلو پاچاهي د یهودا څخه بېله شوې وه تر نن ورځې داسې سختې ورځې نه دي راغلې. هغه به د اشور پاچا راولي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_17.mp3', '', 1761754199, 1761754199),
(48245, 'Isaiah 7:18', 'Isaiah', 7, 18, 'کله چې هغه ورځ راشي، نو څښتن به شپېلۍ ووهي او مصریان به د مچانو په شان د نیل د سیند د لېرې ویالو څخه راشي او اشوریان به لکه د مچیو په شان د خپل وطن څخه راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_18.mp3', '', 1761754199, 1761754199),
(48246, 'Isaiah 7:19', 'Isaiah', 7, 19, 'هغوی به په ژورو وادیو او د ګټانو په درزونو کې ډلې ډلې راشي او د اغزیو په بوټو او په ټولو څړځایونو کې به ځای په ځای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_19.mp3', '', 1761754199, 1761754199),
(48247, 'Isaiah 7:20', 'Isaiah', 7, 20, 'کله چې هغه ورځ راشي، څښتن به د فرات د سیند له بلې غاړې څخه د اشور امپراتور د نایي په توګه اجیر ونیسي او هغه به ستاسو د سرونو، ږیرو او د بدن نور ویښتان وخرایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_20.mp3', '', 1761754199, 1761754199),
(48248, 'Isaiah 7:21', 'Isaiah', 7, 21, 'په هغه ورځ به هېڅوک د یوې ځوانې غوا او دوو مېږو یا وزو څخه زیات ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_21.mp3', '', 1761754199, 1761754199),
(48249, 'Isaiah 7:22', 'Isaiah', 7, 22, 'هغه به دومره شیدې ورکړي چې هغوی مستې وخوړلی شي. هو، یو څو کسان چې په وطن کې ژوندي پاتې دي هغوی به د خوراک دپاره مستې او شات ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_22.mp3', '', 1761754199, 1761754199),
(48250, 'Isaiah 7:23', 'Isaiah', 7, 23, 'کله چې هغه ورځ راشي، د انګورو ډېر ښه باغونه چې په هر یو کې به زر تاکونه وي او هر یو باغ به د یو زر سپینو زرو ټوټو بیه ولري، دا باغونه به له اغزیو او کرکڼو ډک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_23.mp3', '', 1761754199, 1761754199),
(48251, 'Isaiah 7:24', 'Isaiah', 7, 24, 'خلک به هلته د لیندو او غشو سره د ښکار دپاره ورځي، ځکه ټول وطن به د اغزیو او کرکڼو څخه ډک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_24.mp3', '', 1761754199, 1761754199),
(48252, 'Isaiah 7:25', 'Isaiah', 7, 25, 'ټولې کرنیزې غونډۍ به له اغزیو او کرکڼو څخه داسې ډکې شي چې خلک به هلته نه ځي. له هغه نه به داسې ځای جوړ شي چې غویان او پسونه به په کې څریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah7_verse_25.mp3', '', 1761754199, 1761754199),
(48253, 'Psalms 35:1', 'Psalms', 35, 1, 'مخالفت وکړه ته زما د دښمنانو سره ای څښتنه هغوی چې ما سره کړي جنګ ورسره وجنګېږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_1.mp3', '', 1761754199, 1761754199),
(48254, 'Psalms 35:2', 'Psalms', 35, 2, 'ته دې خپل سپر او خپله زغره واخله او راشه ته زما د مرستې لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_2.mp3', '', 1761754199, 1761754199),
(48255, 'Psalms 35:3', 'Psalms', 35, 3, 'خپله نېزه او جنګي تبر دې راپورته کړه ته د هغه چا په وړاندې چې په ما پسې دي دغه ډاډ راکړه چې به ماته راکوې خلاصون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_3.mp3', '', 1761754199, 1761754199),
(48256, 'Psalms 35:4', 'Psalms', 35, 4, 'هغه کسان چې غواړي ما ووژني هغوی دې ماتې سره مخ شي او رسوا دې شي زما په ضد چې دسیسې جوړوي شي دې ناکام او خجالته دې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_4.mp3', '', 1761754199, 1761754199),
(48257, 'Psalms 35:5', 'Psalms', 35, 5, 'دوی دې د بوسو په شان شي چې باد یې الوزوي او فرښته د څښتن دې هغو وځغلوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_5.mp3', '', 1761754199, 1761754199),
(48258, 'Psalms 35:6', 'Psalms', 35, 6, 'په هغه وخت چې فرښته د څښتن وي په هغوی پسې د هغوی لاره دې تیاره شي ښویېدونکې دې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_6.mp3', '', 1761754199, 1761754199),
(48259, 'Psalms 35:7', 'Psalms', 35, 7, 'بې‌سببه هغوی ایښی راته دام دی بې‌سببه راته کنده یې ایستلې چې مې ښکېل کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_7.mp3', '', 1761754199, 1761754199),
(48260, 'Psalms 35:8', 'Psalms', 35, 8, 'بربادي دې ناڅاپي ورباندې راشي دوی دې په خپل دام کې په خپله ګېر شي ودې غورځیږي او برباد دې شي په هغه کنده کې چې دوی کیندلې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_8.mp3', '', 1761754199, 1761754199),
(48261, 'Psalms 35:9', 'Psalms', 35, 9, 'نو بیا زه به شم خوشحاله له سببه د څښتن زه به کړمه خوشحالي ځکه خلاصون یې دی راکړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_9.mp3', '', 1761754199, 1761754199),
(48262, 'Psalms 35:10', 'Psalms', 35, 10, 'د زړه له کومي به څښتن ته وایم: «نشته هېڅوک د ستا په شان څښتنه له زورورو څخه ژغورې ته کمزوري خلک ته خواران خلک ژغورې له ظالمانو»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_10.mp3', '', 1761754199, 1761754199),
(48263, 'Psalms 35:11', 'Psalms', 35, 11, 'بدکاران زما په ضد شاهدي وایي د هغو جرمونو تور راباندې وایي چې خبر ورڅخه نه یم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_11.mp3', '', 1761754199, 1761754199),
(48264, 'Psalms 35:12', 'Psalms', 35, 12, 'د نېکۍ بدل کې ما سره بدي کړي زه یم ډوب نا‌امیدۍ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_12.mp3', '', 1761754199, 1761754199),
(48265, 'Psalms 35:13', 'Psalms', 35, 13, 'خو چې کله به هغوی شول رنځوران نو په تن کولې د غم جامې به ما په روژه نیولو ځان مې ځورولو ما خپل سر به ټیټاوه کړله دعا مې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_13.mp3', '', 1761754199, 1761754199),
(48266, 'Psalms 35:14', 'Psalms', 35, 14, 'لکه چې دوست او یا خپل ورور سره مې ویر کاوه سر به مې ټیټ کړلو له غمه ځینې لکه چې څوک کوي ژړا په خپلې مور باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_14.mp3', '', 1761754199, 1761754199),
(48267, 'Psalms 35:15', 'Psalms', 35, 15, 'کله چې زه وم په تکلیف کې، دوی خوشحاله وو ټول سره راټول شول او ملنډې یې وهلې په ما پردیو خلکو به وهلمه زه او دوامداره سپکاوی به یې کولو زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_15.mp3', '', 1761754199, 1761754199),
(48268, 'Psalms 35:16', 'Psalms', 35, 16, 'د هغو خلکو په شان څوک چې وهي ریشخند ملنډې په ګوډانو باندې دوی چیچل ماته د نفرت غاښونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_16.mp3', '', 1761754199, 1761754199),
(48269, 'Psalms 35:17', 'Psalms', 35, 17, 'ترڅو به ګورې ورته ای څښتنه؟ د دې خلکو د بریدونو نه مې خلاص کړه د دې زمریانو نه مې قیمتي ژوند وژغوره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_17.mp3', '', 1761754199, 1761754199),
(48270, 'Psalms 35:18', 'Psalms', 35, 18, 'بیا به د ستا د قوم په غونډه کې ستا شکر کړمه د هغو ټولو مخکې زه به ستا ثنا وایمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_18.mp3', '', 1761754199, 1761754199),
(48271, 'Psalms 35:19', 'Psalms', 35, 19, 'زما بې‌سببه دښمنان مه پرېږده چې شي خوشحاله زما په ماتې باندې مه یې پرېږده چې بې‌سببه کړي زما نه کرکه چې کړي خندا د خوشحالۍ زما په غم باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_19.mp3', '', 1761754199, 1761754199),
(48272, 'Psalms 35:20', 'Psalms', 35, 20, 'د خیر خبرې نه کوي د شر خبرې کاندي د هغوی پسې کوي غلطې خبرې څوک چې په سوله کې ژوندون تېروي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_20.mp3', '', 1761754199, 1761754199),
(48273, 'Psalms 35:21', 'Psalms', 35, 21, 'دوی په ما لګوي تور او وهي چیغې: «واه! واه! تا چې څه وکړل مونږ ولیدل»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_21.mp3', '', 1761754199, 1761754199),
(48274, 'Psalms 35:22', 'Psalms', 35, 22, 'خو ای څښتنه ولیدل تا هرڅه نو چوپ کېږه مه څښتنه ته له ما مه لېرې کېږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_22.mp3', '', 1761754199, 1761754199),
(48275, 'Psalms 35:23', 'Psalms', 35, 23, 'ای څښتنه، شه راپورته او دفاع راڅخه وکړه شه راپورته، زما خدایه، ته زما د دعوې وکړه وکالت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_23.mp3', '', 1761754199, 1761754199),
(48276, 'Psalms 35:24', 'Psalms', 35, 24, 'ته عادل یې ای څښتنه، نو زما بې‌ګناهي کړه ته اعلان ته زما دښمنان مه پرېږده چې ما باندې خوشحال شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_24.mp3', '', 1761754199, 1761754199),
(48277, 'Psalms 35:25', 'Psalms', 35, 25, 'هغوی مه پرېږده چې ووایي خپل منځ کې: «مونږ هغه له منځه یووړ هغه څه چې مونږ غوښتل هغسې وشول!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_25.mp3', '', 1761754199, 1761754199),
(48278, 'Psalms 35:26', 'Psalms', 35, 26, 'څوک چې زما په بدبختۍ کې خوشحالي کړي هغوی دې سمه ماتې وخوري وارخطا دې شي څوک چې خپل ځان له ما بهتر ګڼي شي په جامو د شرم پټ دې او رسوا دې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_26.mp3', '', 1761754199, 1761754199),
(48279, 'Psalms 35:27', 'Psalms', 35, 27, 'هغوی چې غواړي ما برحق وویني د خوشحالۍ چیغې دې ووهي او تل دې وایي: «څومره لوی دی څښتن! په سوکالۍ د خپل خادم باندې خوشحاله دی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_27.mp3', '', 1761754199, 1761754199),
(48280, 'Psalms 35:28', 'Psalms', 35, 28, 'ستا عدالت به بیا په ژبه زه بیان کړمه او ټوله ورځ به زه د ستا ثنا صفت کړمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms35_verse_28.mp3', '', 1761754199, 1761754199),
(48281, 'Numbers 29:1', 'Numbers', 29, 1, 'هر کال د اوومې میاشتې په لومړۍ ورځ تاسې د عبادت دپاره سره راټول شئ او باید هېڅ ورځنی کار ونه کړئ. په هغې ورځ باید سرني ووهل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_1.mp3', '', 1761754199, 1761754199),
(48282, 'Numbers 29:2', 'Numbers', 29, 2, 'څښتن ته سوځېدونکې نذرانه یعنې یوه خوشبویي چې په هغه باندې ښه لګیږي وړاندې کړئ: یو خوسی، یو پسه او اووه یو کلن وري، ټول باید بې عیبه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_2.mp3', '', 1761754199, 1761754199),
(48283, 'Numbers 29:3', 'Numbers', 29, 3, 'د غویي سره باید درې کیلو ګرامه ښه اوړه چې د زیتونو تېل ورسره ګډ وي د غلې دانې د نذرانې په توګه وړاندې شي. دوه کیلو ګرامه اوړه چې تېل ورسره ګډ وي باید د پسه سره وړاندې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_3.mp3', '', 1761754199, 1761754199),
(48284, 'Numbers 29:4', 'Numbers', 29, 4, 'او یو کیلو ګرام اوړه چې تېل ورسره ګډ وي باید د هر وري سره وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_4.mp3', '', 1761754199, 1761754199),
(48285, 'Numbers 29:5', 'Numbers', 29, 5, 'همدارنګه یو سېرلی د ګناه د نذرانې په توګه وړاندې کړئ او په دې ډول د قوم دپاره کفاره ادا کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_5.mp3', '', 1761754199, 1761754199),
(48286, 'Numbers 29:6', 'Numbers', 29, 6, 'دا نذرانې دې د میاشتې د اولې ورځې د عادي سوځېدونکې نذرانې او د هغې د غلې دانې د نذرانې او ورځنۍ سوځېدونکې نذرانې او د هغې د غلې دانې د نذرانې او د څښلو د نذرانې څخه علاوه وړاندې شي. دا هغه نذرانې دي چې په اور باندې څښتن ته تیاریږي او بوی یې په هغه باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_6.mp3', '', 1761754199, 1761754199),
(48287, 'Numbers 29:7', 'Numbers', 29, 7, 'د اوومې میاشتې په لسمه ورځ د عبادت دپاره راټول شئ. په دې ورځ روژه ونیسئ او کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_7.mp3', '', 1761754199, 1761754199),
(48288, 'Numbers 29:8', 'Numbers', 29, 8, 'څښتن ته یوه سوځېدونکې نذرانه وړاندې کړئ، یعنې یوه خوشبویي چې په هغه باندې ښه لګیږي: یو خوسی، یو پسه او اووه یو کلن وري، دا ټول باید هېڅ عیب ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_8.mp3', '', 1761754199, 1761754199),
(48289, 'Numbers 29:9', 'Numbers', 29, 9, 'د غویي سره باید درې کیلو ګرامه ښه اوړه چې د زیتونو تېل ورسره ګډ وي، د غلې دانې د نذرانې په توګه وړاندې شي. دوه کیلو ګرامه اوړه چې تېل ورسره ګډ وي، باید د پسه سره وړاندې شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_9.mp3', '', 1761754199, 1761754199),
(48290, 'Numbers 29:10', 'Numbers', 29, 10, 'او یو کیلو ګرام اوړه چې تېل ورسره ګډ وي، باید د هر وري سره وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_10.mp3', '', 1761754199, 1761754199),
(48291, 'Numbers 29:11', 'Numbers', 29, 11, 'همدارنګه برسېره په هغه سېرلي چې د خلکو د کفارې دپاره قرباني کیږي، د ورځنۍ سوځېدونکې نذرانې او د هغې د غلې دانې د نذرانې او د څښلو د نذرانې څخه یو سېرلی د ګناه د نذرانې په توګه قرباني کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_11.mp3', '', 1761754199, 1761754199),
(48292, 'Numbers 29:12', 'Numbers', 29, 12, 'د اوومې میاشتې په پنځلسمه ورځ د عبادت دپاره سره راټول شئ. اووه ورځې دا اختر څښتن ته د درناوي دپاره ولمانځئ او هېڅ ورځنی کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_12.mp3', '', 1761754199, 1761754199),
(48293, 'Numbers 29:13', 'Numbers', 29, 13, 'په لومړۍ ورځ څښتن ته دیارلس خوسیان، دوه پسونه او څوارلس یو کلن وري چې په ټولو کې هېڅ عیب نه وي، د سوځېدونکې نذرانې په توګه وړاندې کړئ. د داسې نذرانې بوی په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_13.mp3', '', 1761754199, 1761754199),
(48294, 'Numbers 29:14', 'Numbers', 29, 14, 'د هر غویي سره باید درې کیلو ګرامه ښه اوړه چې د زیتونو تېل ورسره ګډ وي، د غلې دانې د نذرانې په توګه وړاندې کړئ. دوه کیلو ګرامه اوړه چې تېل ورسره ګډ وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_14.mp3', '', 1761754199, 1761754199),
(48295, 'Numbers 29:15', 'Numbers', 29, 15, 'د دې څوارلسو وریو څخه د هر وري سره وړاندې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_15.mp3', '', 1761754199, 1761754199),
(48296, 'Numbers 29:16', 'Numbers', 29, 16, 'همدارنګه یو سېرلی د ګناه د نذرانې په توګه وړاندې کړئ. دا دې برسېره پر ورځنۍ سوځېدونکې نذرانې او د هغې د غلې دانې او څښلو د نذرانې وړاندې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_16.mp3', '', 1761754199, 1761754199),
(48297, 'Numbers 29:17', 'Numbers', 29, 17, 'په دوهمه ورځ دولس خوسیان، دوه پسونه او څوارلس یو کلن وري وړاندې کړئ، دا ټول دې هېڅ عیب ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_17.mp3', '', 1761754199, 1761754199),
(48298, 'Numbers 29:20', 'Numbers', 29, 20, 'په درېمه ورځ یوولس غویان، دوه پسونه او څوارلس یو کلن وري وړاندې کړئ، دا ټول دې هېڅ عیب ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_20.mp3', '', 1761754199, 1761754199),
(48299, 'Numbers 29:23', 'Numbers', 29, 23, 'په څلورمه ورځ لس غویان، دوه پسونه او څوارلس یو کلن وري وړاندې کړئ، دا ټول دې هېڅ عیب ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_23.mp3', '', 1761754199, 1761754199),
(48300, 'Numbers 29:26', 'Numbers', 29, 26, 'په پنځمه ورځ نهه غویان، دوه پسونه او څوارلس یو کلن وري وړاندې کړئ، دا ټول دې هېڅ عیب ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_26.mp3', '', 1761754199, 1761754199),
(48301, 'Numbers 29:29', 'Numbers', 29, 29, 'په شپږمه ورځ اته غویان، دوه پسونه او څوارلس یو کلن وري وړاندې کړئ، دا ټول دې هېڅ عیب ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_29.mp3', '', 1761754199, 1761754199),
(48302, 'Numbers 29:32', 'Numbers', 29, 32, 'په اوومه ورځ اووه غویان، دوه پسونه او څوارلس یو کلن وري وړاندې کړئ، دا ټول دې هېڅ عیب ونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_32.mp3', '', 1761754199, 1761754199),
(48303, 'Numbers 29:35', 'Numbers', 29, 35, 'په اتمه ورځ د عبادت دپاره راټول شئ او هېڅ ورځنی کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_35.mp3', '', 1761754199, 1761754199),
(48304, 'Numbers 29:36', 'Numbers', 29, 36, 'څښتن ته یو خوسی، یو پسه او اووه یو کلن وري چې په ټولو کې کوم عیب نه وي د یوې سوځېدونکې نذرانې په توګه وړاندې کړئ. د داسې نذرانې بوی په هغه باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_36.mp3', '', 1761754199, 1761754199),
(48305, 'Numbers 29:39', 'Numbers', 29, 39, 'دا مقررات د سوځېدونکو نذرانو، د غلو دانو د نذرانو، د څښلو د نذرانو او د سلامتۍ د نذرانو په اړه دي چې تاسو یې باید په خپلو ټاکل شویو اخترونو کې څښتن ته ورکړئ. دا برسېره په هغو نذرانو دي چې تاسو یې د نذر د ورکولو یا د خپلې خوښې نذرانو په توګه ورکوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_39.mp3', '', 1761754199, 1761754199),
(48306, 'Numbers 29:40', 'Numbers', 29, 40, 'نو موسی د اسراییلو قوم ته هغه ټول شیان وویل چې څښتن ورته حکم کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers29_verse_40.mp3', '', 1761754199, 1761754199),
(48307, 'Zechariah 5:1', 'Zechariah', 5, 1, 'ما بيا وکتل، هلته په هوا کښې زما په وړاندې يو کولاو شوے طومار وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_1.mp3', '', 1761754199, 1761754199),
(48308, 'Zechariah 5:2', 'Zechariah', 5, 2, 'نو فرښتې زما نه تپوس وکړو چې، ”تا ته څۀ ښکارى؟“ ما جواب ورکړو چې، ”ما ته په هوا کښې يو کولاو طومار ښکارى چې لس ګزه اوږد او پينځۀ ګزه پلن دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_2.mp3', '', 1761754199, 1761754199),
(48309, 'Zechariah 5:3', 'Zechariah', 5, 3, 'او هغې ما ته وفرمائيل، ”دا هغه لعنت دے چې په ټوله دُنيا کښې به راشى، ځکه څۀ چې د دۀ په يو اړخ کښې ليکلے شوى دى د هغې په مطابق، هر يو غل به وشړلے شى، او څۀ چې د دې په بل اړخ ليکلے شوى دى د هغې په مطابق، هر څوک چې د دروغو قسمونه خورى هغوئ به لرې کړے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_3.mp3', '', 1761754199, 1761754199),
(48310, 'Zechariah 5:4', 'Zechariah', 5, 4, 'مالِک خُدائ ربُ الافواج فرمائى، زۀ به دا لعنت بهر ولېږم، او دا به د غل کور ته او د هغه چا کور ته ورننوځى څوک چې زما په نوم د دروغو قسمونه خورى. دا به په هغه کور کښې پاتې شى او دا به د دې لرګى او کاڼى دواړه په پوره توګه تباه کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah5_verse_4.mp3', '', 1761754199, 1761754199);